package com.example.securecam

import java.security.MessageDigest
import java.util.Base64

// SecureCam v2 provenance core. Pure Kotlin (no android.*) so it runs in JVM unit tests.
// Must stay bit-identical with securecam-core.js — ProvenanceTest checks this against
// vectors generated by the JavaScript implementation.

/** scfp1 visual fingerprint: 128x128 luma + 32x32 Cb/Cr thumbnails and a 64-bit DCT pHash. */
object Scfp {
    const val ALG = "scfp1"
    const val N = 128
    const val NC = 32
    const val THUMB_BYTES = N * N + 2 * NC * NC
    const val MIN_SIDE = N

    // DCT basis for the 8 lowest frequencies over 32 samples, scaled to integers.
    internal val COS: IntArray = IntArray(8 * 32).also { t ->
        for (u in 0 until 8) for (x in 0 until 32)
            t[u * 32 + x] = Math.round(4096.0 * Math.cos((2 * x + 1) * u * Math.PI / 64)).toInt()
    }

    class Thumbs(val y: ByteArray, val cb: ByteArray, val cr: ByteArray) {
        fun bytes(): ByteArray = y + cb + cr
    }

    private fun clamp255(v: Int) = if (v < 0) 0 else if (v > 255) 255 else v

    /** [pixels] are ARGB ints (Bitmap.getPixels layout) of a [w] x [h] image. */
    fun fromArgb(pixels: IntArray, w: Int, h: Int): Thumbs {
        require(w >= MIN_SIDE && h >= MIN_SIDE) { "image too small to fingerprint (${w}x$h)" }
        val colCell = IntArray(w) { (it.toLong() * N / w).toInt() }
        val sY = IntArray(N * N)
        val sCb = IntArray(N * N)
        val sCr = IntArray(N * N)
        val cnt = IntArray(N * N)
        for (yy in 0 until h) {
            val rowBase = (yy.toLong() * N / h).toInt() * N
            var i = yy * w
            for (x in 0 until w) {
                val p = pixels[i++]
                val r = (p shr 16) and 0xFF
                val g = (p shr 8) and 0xFF
                val b = p and 0xFF
                val cell = rowBase + colCell[x]
                sY[cell] += (19595 * r + 38470 * g + 7471 * b + 32768) shr 16
                sCb[cell] += clamp255(((-11059 * r - 21709 * g + 32768 * b + 32768) shr 16) + 128)
                sCr[cell] += clamp255(((32768 * r - 27439 * g - 5329 * b + 32768) shr 16) + 128)
                cnt[cell]++
            }
        }
        val y = ByteArray(N * N) { ((2 * sY[it] + cnt[it]) / (2 * cnt[it])).toByte() }
        val f = N / NC
        val cb = ByteArray(NC * NC)
        val cr = ByteArray(NC * NC)
        for (a in 0 until NC) for (b in 0 until NC) {
            var tb = 0; var tr = 0; var tn = 0
            for (r in a * f until (a + 1) * f) for (c in b * f until (b + 1) * f) {
                val k = r * N + c
                tb += sCb[k]; tr += sCr[k]; tn += cnt[k]
            }
            cb[a * NC + b] = ((2 * tb + tn) / (2 * tn)).toByte()
            cr[a * NC + b] = ((2 * tr + tn) / (2 * tn)).toByte()
        }
        return Thumbs(y, cb, cr)
    }

    /** Grid of the image rotated clockwise by [deg] (0/90/180/270). */
    fun rotateGrid(g: ByteArray, n: Int, deg: Int): ByteArray {
        val d = ((deg % 360) + 360) % 360
        require(d % 90 == 0) { "rotation must be a multiple of 90" }
        if (d == 0) return g.copyOf()
        val out = ByteArray(n * n)
        for (r in 0 until n) for (c in 0 until n) {
            out[r * n + c] = when (d) {
                90 -> g[(n - 1 - c) * n + r]
                180 -> g[(n - 1 - r) * n + (n - 1 - c)]
                else -> g[c * n + (n - 1 - r)]
            }
        }
        return out
    }

    fun rotate(t: Thumbs, deg: Int) = Thumbs(rotateGrid(t.y, N, deg), rotateGrid(t.cb, NC, deg), rotateGrid(t.cr, NC, deg))

    /** 64-bit DCT perceptual hash of the luma thumbnail as 16 hex chars. */
    fun phash(y: ByteArray): String {
        val p = IntArray(32 * 32)
        for (r in 0 until N) for (c in 0 until N) p[(r shr 2) * 32 + (c shr 2)] += y[r * N + c].toInt() and 0xFF
        val t = LongArray(32 * 8)
        for (r in 0 until 32) for (u in 0 until 8) {
            var s = 0L
            for (x in 0 until 32) s += p[r * 32 + x].toLong() * COS[u * 32 + x]
            t[r * 8 + u] = s
        }
        val d = LongArray(64)
        for (v in 0 until 8) for (u in 0 until 8) {
            var s = 0L
            for (r in 0 until 32) s += COS[v * 32 + r].toLong() * t[r * 8 + u]
            d[v * 8 + u] = s
        }
        val sorted = d.sortedArray()
        val m2 = sorted[31] + sorted[32]
        val bytes = ByteArray(8)
        for (k in 0 until 64) if (2 * d[k] > m2) bytes[k shr 3] = (bytes[k shr 3].toInt() or (1 shl (7 - (k and 7)))).toByte()
        return ScCrypto.hex(bytes)
    }
}

/** The signed manifest: the phone's exact UTF-8 bytes are what gets signed and verified. */
object ScManifest {
    fun build(
        app: String, capturedUtc: String, fileSha256: String, phash: String, thumbSha256: String,
        width: Int, height: Int, keyId: String, security: String
    ): ByteArray =
        ("{\"v\":2,\"app\":${q(app)},\"captured\":${q(capturedUtc)},\"file_sha256\":${q(fileSha256)}," +
            "\"fp\":{\"alg\":\"${Scfp.ALG}\",\"phash\":${q(phash)},\"thumb_sha256\":${q(thumbSha256)},\"w\":$width,\"h\":$height}," +
            "\"key\":${q(keyId)},\"sec\":${q(security)}}").toByteArray(Charsets.UTF_8)

    private fun q(s: String): String {
        val sb = StringBuilder("\"")
        for (ch in s) when {
            ch == '"' -> sb.append("\\\"")
            ch == '\\' -> sb.append("\\\\")
            ch < ' ' -> sb.append(String.format("\\u%04x", ch.code))
            else -> sb.append(ch)
        }
        return sb.append('"').toString()
    }
}

/** Block appended after the JPEG's FF D9 marker. Image viewers ignore it. */
object ScTrailer {
    fun v2(manifest: ByteArray, rawSig: ByteArray, spki: ByteArray, thumb: ByteArray): ByteArray {
        val b64 = Base64.getEncoder()
        return ("||SECURECAM_V2||M:${b64.encodeToString(manifest)}|S:${b64.encodeToString(rawSig)}" +
            "|P:${b64.encodeToString(spki)}|T:${b64.encodeToString(thumb)}||SECURECAM_END||").toByteArray(Charsets.US_ASCII)
    }

    /** JSON body for POST /api/records on the registry server. */
    fun registryPayload(manifest: ByteArray, rawSig: ByteArray, spki: ByteArray, thumb: ByteArray, chain: List<ByteArray>): String {
        val b64 = Base64.getEncoder()
        return "{\"manifest\":\"${b64.encodeToString(manifest)}\",\"sig\":\"${b64.encodeToString(rawSig)}\"," +
            "\"pub\":\"${b64.encodeToString(spki)}\",\"thumb\":\"${b64.encodeToString(thumb)}\"," +
            "\"chain\":[${chain.joinToString(",") { "\"${b64.encodeToString(it)}\"" }}]}"
    }
}

object ScCrypto {
    fun sha256(b: ByteArray): ByteArray = MessageDigest.getInstance("SHA-256").digest(b)

    fun hex(b: ByteArray): String {
        val sb = StringBuilder(b.size * 2)
        for (x in b) sb.append(String.format("%02x", x.toInt() and 0xFF))
        return sb.toString()
    }

    /** Converts Java's ASN.1 DER ECDSA signature to the raw r||s form WebCrypto expects. */
    fun derToRawEcdsa(der: ByteArray, componentSize: Int = 32): ByteArray {
        var offset = 1
        var seqLen = der[offset].toInt() and 0xFF; offset++
        if (seqLen and 0x80 != 0) {
            val n = seqLen and 0x7F
            seqLen = 0
            repeat(n) { seqLen = (seqLen shl 8) or (der[offset].toInt() and 0xFF); offset++ }
        }
        fun readInt(): ByteArray {
            offset++
            var len = der[offset].toInt() and 0xFF; offset++
            if (len and 0x80 != 0) {
                val n = len and 0x7F
                len = 0
                repeat(n) { len = (len shl 8) or (der[offset].toInt() and 0xFF); offset++ }
            }
            val bytes = der.copyOfRange(offset, offset + len)
            offset += len
            return if (bytes.size > 1 && bytes[0] == 0.toByte()) bytes.copyOfRange(1, bytes.size) else bytes
        }
        fun pad(b: ByteArray) = if (b.size == componentSize) b else
            ByteArray(componentSize).also { System.arraycopy(b, 0, it, componentSize - b.size, b.size) }
        val r = pad(readInt())
        val s = pad(readInt())
        return r + s
    }
}
